citation(eu_reg_2016_679_art_12_2, [label - 'Regulation (EU) 2016/679 Art 12(2), second sentence (controller demonstrates it cannot identify the data subject)', ref - '02016R0679-20160504#parag_012.002', verbatim - 'the controller shall not refuse to act on the request of the data subject for exercising his or her rights under Articles 15 to 22, unless the controller demonstrates that it is not in a position to identify the data subject']).
citation(eu_reg_2016_679_art_12_5, [label - 'Regulation (EU) 2016/679 Art 12(5) (manifestly unfounded or excessive requests)', ref - '02016R0679-20160504#parag_012.005', verbatim - 'Where requests from a data subject are manifestly unfounded or excessive, in particular because of their repetitive character, the controller may either']).
citation(eu_reg_2016_679_art_12_6, [label - 'Regulation (EU) 2016/679 Art 12(6) (reasonable doubts about identity)', ref - '02016R0679-20160504#parag_012.006', verbatim - 'where the controller has reasonable doubts concerning the identity of the natural person making the request referred to in Articles 15 to 21, the controller may request the provision of additional information necessary to confirm the identity of the data subject']).
citation(eu_reg_2016_679_art_17_1, [label - 'Regulation (EU) 2016/679 Art 17(1) (right to erasure, opening words)', ref - '02016R0679-20160504#parag_017.001', verbatim - 'The data subject shall have the right to obtain from the controller the erasure of personal data concerning him or her without undue delay']).
citation(eu_reg_2016_679_art_17_1_a, [label - 'Regulation (EU) 2016/679 Art 17(1)(a) (data no longer necessary)', ref - '02016R0679-20160504#point_017.001_a', verbatim - 'the personal data are no longer necessary in relation to the purposes for which they were collected or otherwise processed']).
citation(eu_reg_2016_679_art_17_1_b, [label - 'Regulation (EU) 2016/679 Art 17(1)(b) (consent withdrawn, no other legal ground)', ref - '02016R0679-20160504#point_017.001_b', verbatim - 'the data subject withdraws consent on which the processing is based according to point (a) of Article 6(1), or point (a) of Article 9(2), and where there is no other legal ground for the processing']).
citation(eu_reg_2016_679_art_17_1_c, [label - 'Regulation (EU) 2016/679 Art 17(1)(c) (objection under Art 21)', ref - '02016R0679-20160504#point_017.001_c', verbatim - 'the data subject objects to the processing pursuant to Article 21(1) and there are no overriding legitimate grounds for the processing, or the data subject objects to the processing pursuant to Article 21(2)']).
citation(eu_reg_2016_679_art_17_1_d, [label - 'Regulation (EU) 2016/679 Art 17(1)(d) (unlawfully processed)', ref - '02016R0679-20160504#point_017.001_d', verbatim - 'the personal data have been unlawfully processed']).
citation(eu_reg_2016_679_art_17_1_e, [label - 'Regulation (EU) 2016/679 Art 17(1)(e) (legal obligation to erase)', ref - '02016R0679-20160504#point_017.001_e', verbatim - 'the personal data have to be erased for compliance with a legal obligation in Union or Member State law to which the controller is subject']).
citation(eu_reg_2016_679_art_17_1_f, [label - 'Regulation (EU) 2016/679 Art 17(1)(f) (information society services offer, Art 8(1))', ref - '02016R0679-20160504#point_017.001_f', verbatim - 'the personal data have been collected in relation to the offer of information society services referred to in Article 8(1)']).
citation(eu_reg_2016_679_art_17_3_a, [label - 'Regulation (EU) 2016/679 Art 17(3)(a) (freedom of expression and information)', ref - '02016R0679-20160504#point_017.003_a', verbatim - 'for exercising the right of freedom of expression and information']).
citation(eu_reg_2016_679_art_17_3_b, [label - 'Regulation (EU) 2016/679 Art 17(3)(b) (legal obligation, public interest task, official authority)', ref - '02016R0679-20160504#point_017.003_b', verbatim - 'for compliance with a legal obligation which requires processing by Union or Member State law to which the controller is subject or for the performance of a task carried out in the public interest or in the exercise of official authority vested in the controller']).
citation(eu_reg_2016_679_art_17_3_c, [label - 'Regulation (EU) 2016/679 Art 17(3)(c) (public health)', ref - '02016R0679-20160504#point_017.003_c', verbatim - 'for reasons of public interest in the area of public health in accordance with points (h) and (i) of Article 9(2) as well as Article 9(3)']).
citation(eu_reg_2016_679_art_17_3_d, [label - 'Regulation (EU) 2016/679 Art 17(3)(d) (archiving, research, statistics)', ref - '02016R0679-20160504#point_017.003_d', verbatim - 'for archiving purposes in the public interest, scientific or historical research purposes or statistical purposes in accordance with Article 89(1) in so far as the right referred to in paragraph 1 is likely to render impossible or seriously impair the achievement of the objectives of that processing']).
citation(eu_reg_2016_679_art_17_3_e, [label - 'Regulation (EU) 2016/679 Art 17(3)(e) (legal claims)', ref - '02016R0679-20160504#point_017.003_e', verbatim - 'for the establishment, exercise or defence of legal claims']).
citation(eu_reg_2016_679_art_23_1, [label - 'Regulation (EU) 2016/679 Art 23(1) (legislative restrictions, opening words)', ref - '02016R0679-20160504#parag_023.001', verbatim - 'Union or Member State law to which the data controller or processor is subject may restrict by way of a legislative measure the scope of the obligations and rights provided for in Articles 12 to 22 and Article 34']).
